"""
config_precedence_merge.py

Implements merge_settings(defaults, file_config, env) -> dict
with precedence: defaults < file_config < environment variables.

Also implements redact_secrets(config: dict) -> dict which returns a deep copy
where keys named password, token, secret, or api_key are replaced with
"<redacted>" at any nesting level.
"""

import copy


# Keys whose values should be redacted
_SENSITIVE_KEYS = {"password", "token", "secret", "api_key"}


def _parse_bool(value: str):
    """Return True/False if value is 'true'/'false' (case-insensitive), else None."""
    lower = value.lower()
    if lower == "true":
        return True
    if lower == "false":
        return False
    return None


def _parse_int(value: str):
    """Return int if value is a base-10 integer string, else None."""
    try:
        return int(value, 10)
    except (ValueError, TypeError):
        return None


def _parse_list(value: str):
    """Return list of trimmed non-empty strings if value contains a comma, else None."""
    if "," in value:
        return [p.strip() for p in value.split(",") if p.strip()]
    return None


def _parse_value(value: str):
    """Parse a string value into bool, int, list, or str."""
    result = _parse_bool(value)
    if result is not None:
        return result
    result = _parse_int(value)
    if result is not None:
        return result
    result = _parse_list(value)
    if result is not None:
        return result
    return value


def _deep_merge(base: dict, override: dict) -> dict:
    """
    Deep-merge override into base, returning a new dict.
    Neither base nor override is mutated.
    """
    result = copy.deepcopy(base)
    for key, value in override.items():
        if key in result and isinstance(result[key], dict) and isinstance(value, dict):
            result[key] = _deep_merge(result[key], value)
        else:
            result[key] = copy.deepcopy(value)
    return result


def _segments_from_key(raw_key: str, prefix: str):
    """Return lowercased segments from an APP__-prefixed key, or None if not prefixed."""
    if not raw_key.startswith(prefix):
        return None
    remainder = raw_key[len(prefix):]
    return [seg.lower() for seg in remainder.split("__")]


def _insert_nested(nested: dict, segments: list, value) -> None:
    """Insert a parsed value into a nested dict at the location described by segments."""
    current = nested
    for seg in segments[:-1]:
        if seg not in current or not isinstance(current[seg], dict):
            current[seg] = {}
        current = current[seg]
    current[segments[-1]] = value


def _env_to_nested(env: dict) -> dict:
    """
    Convert APP__-prefixed environment variables into a nested dict.
    Keys are split on '__', lowercased per segment.
    Values are parsed via _parse_value.
    """
    nested = {}
    prefix = "APP__"
    for raw_key, raw_value in env.items():
        segments = _segments_from_key(raw_key, prefix)
        if segments is None:
            continue
        _insert_nested(nested, segments, _parse_value(raw_value))
    return nested


def merge_settings(defaults: dict, file_config: dict, env: dict) -> dict:
    """
    Merge settings with precedence: defaults < file_config < environment variables.

    Parameters
    ----------
    defaults : dict
        Base default settings.
    file_config : dict
        Settings loaded from a configuration file.
    env : dict[str, str]
        Environment variables; those starting with APP__ are parsed and applied.

    Returns
    -------
    dict
        A new merged settings dictionary. Input dicts are never mutated.

    Raises
    ------
    TypeError
        If any of the arguments is not a dict, or if any key or value in env
        is not a str.
    """
    if not isinstance(defaults, dict):
        raise TypeError(
            f"'defaults' must be a dict, got {type(defaults).__name__!r}"
        )
    if not isinstance(file_config, dict):
        raise TypeError(
            f"'file_config' must be a dict, got {type(file_config).__name__!r}"
        )
    if not isinstance(env, dict):
        raise TypeError(
            f"'env' must be a dict, got {type(env).__name__!r}"
        )
    for raw_key, raw_value in env.items():
        if not isinstance(raw_key, str):
            raise TypeError(
                f"All keys in 'env' must be str, got {type(raw_key).__name__!r}"
            )
        if not isinstance(raw_value, str):
            raise TypeError(
                f"All values in 'env' must be str, got {type(raw_value).__name__!r}"
                f" (key={raw_key!r})"
            )

    result = copy.deepcopy(defaults)
    result = _deep_merge(result, file_config)
    result = _deep_merge(result, _env_to_nested(env))
    return result


def redact_secrets(config: dict) -> dict:
    """
    Return a deep copy of config where any key named password, token, secret,
    or api_key (at any nesting level) has its value replaced with "<redacted>".

    Parameters
    ----------
    config : dict
        The settings dictionary to redact.

    Returns
    -------
    dict
        A new dictionary with sensitive values replaced. Input is never mutated.

    Raises
    ------
    TypeError
        If config is not a dict.
    """
    if not isinstance(config, dict):
        raise TypeError(
            f"'config' must be a dict, got {type(config).__name__!r}"
        )

    result = {}
    for key, value in config.items():
        if key in _SENSITIVE_KEYS:
            result[key] = "<redacted>"
        elif isinstance(value, dict):
            result[key] = redact_secrets(value)
        else:
            result[key] = copy.deepcopy(value)
    return result
